380	// 로그인 직후 모달로 표시. '하루동안 열지 않음' 체크 시 글 단위 24h dismiss.
381	// 학부모(role=parent)는 표시 대상 제외.
382	function showLoginUpdatePopup() {
383	  if (!currentUser) return;
384	  if (currentUser.role === 'parent') return;
385	  if (document.getElementById('loginUpdatePopup')) return; // 중복 방지
386	
387	  supaFetch('madi_global_notices?show_as_login_popup=eq.true&order=created_at.desc&limit=1', 'GET')
388	    .then(function(rows) {
389	      if (!Array.isArray(rows) || rows.length === 0) return; // 활성 팝업 없음
390	      var n = rows[0];
391	      // 글 단위 dismiss 확인
392	      var dismissKey = 'madi_update_popup_dismiss_' + n.id;
393	      var until = parseInt(localStorage.getItem(dismissKey) || '0', 10);
394	      if (until && Date.now() < until) return; // 24h 이내 → 표시 안 함
395	      _renderLoginUpdatePopup(n, dismissKey);
396	    })
397	    .catch(function() { /* 조용히 실패 (네트워크 오류는 토스트로 사용자 흐름 방해 안 함) */ });
