1	// ══════════════════════
2	// madi-15.js — 학부모 포털 전용 로직
3	// ══════════════════════
4	
5	var _parentCurrentTab = 'home';
6	
7	// ─── 탭 전환 ───
8	function switchParentTab(tab) {
9	  _parentCurrentTab = tab;
10	  window._parentActiveTab = tab; // setActiveParentChild 가 재로드 대상 판별에 사용
11	  var tabs = ['home','sched','report','notice'];
12	  tabs.forEach(function(t) {
13	    var panel = document.getElementById('parentPanel' + t.charAt(0).toUpperCase() + t.slice(1));
14	    if (panel) panel.style.display = (t === tab) ? 'block' : 'none';
15	    // ★ 중복 ID 처리: parentTabs + 사이드바 버튼 모두 active 업데이트
16	    var btnId = 'ptBtn' + t.charAt(0).toUpperCase() + t.slice(1);
17	    document.querySelectorAll('[id="' + btnId + '"]').forEach(function(btn) {
18	      btn.classList.toggle('active', t === tab);
19	    });
20	  });
21	  if (tab === 'home')   loadParentHome();
22	  if (tab === 'sched')  loadParentSched();
23	  if (tab === 'report') loadParentReport();
24	  if (tab === 'notice') loadParentNotice();
25	}
26	
27	// ─── 내 아동 정보 가져오기 (공통) ───
28	// 다자녀 학부모 지원: window._parentChildren 에 전체 배열 캐싱, _parentActiveIdx 로 활성 자녀 추적
29	// onNoChild: 아동 미연결 시 호출되는 콜백 (온보딩용)
30	function getMyChildInfo(callback, onNoChild) {
31	  if (!currentUser || currentUser.role !== 'parent') return;
32	
33	  function _emit() {
34	    var arr = window._parentChildren;
35	    var idx = window._parentActiveIdx || 0;
36	    if (!arr || arr.length === 0) {
37	      if (typeof onNoChild === 'function') onNoChild();
38	      return;
39	    }
40	    if (idx < 0 || idx >= arr.length) idx = 0;
41	    var c = arr[idx];
42	    // 하위 호환 캐시 (window._parentChildId / Center / Name 을 보는 기존 코드용)
43	    window._parentChildId   = c.child_id;
44	    window._parentCenterId  = c.center_id;
45	    window._parentChildName = c.name || '';
46	    callback(c.child_id, c.center_id);
47	  }
48	
49	  // 캐시 유효성 — currentUser.id 가 캐싱된 시점과 동일할 때만 신뢰
50	  if (window._parentChildren && window._parentCacheUserId === currentUser.id) {
51	    _emit();
52	    return;
53	  }
54	  // 캐시 무효 → 재조회
55	  window._parentChildren    = null;
56	  window._parentActiveIdx   = 0;
57	  window._parentChildId     = null;
58	  window._parentCenterId    = null;
59	  window._parentChildName   = '';
60	  window._parentCacheUserId = null;
61	
62	  supaFetch('madi_parent_children?parent_user_id=eq.' + encodeURIComponent(currentUser.id) + '&select=child_id,center_id', 'GET')
63	    .then(function(rows) {
64	      if (!Array.isArray(rows) || rows.length === 0) {
65	        window._parentChildren = [];
66	        window._parentCacheUserId = currentUser.id;
67	        if (typeof onNoChild === 'function') onNoChild();
68	        return;
69	      }
70	      // 자녀 이름까지 함께 조회 후 캐싱
71	      var ids = rows.map(function(r){ return encodeURIComponent(r.child_id); }).join(',');
72	      return supaFetch('madi_children?id=in.(' + ids + ')&select=id,data', 'GET')
73	        .then(function(children) {
74	          var nameMap = {};
75	          if (Array.isArray(children)) {
76	            children.forEach(function(c){ nameMap[String(c.id)] = (c.data && c.data.name) || ''; });
77	          }
78	          window._parentChildren = rows.map(function(r){
79	            return { child_id: r.child_id, center_id: r.center_id, name: nameMap[String(r.child_id)] || '' };
80	          });
81	          window._parentActiveIdx   = 0;
82	          window._parentCacheUserId = currentUser.id;
83	          _emit();
84	        });
85	    }).catch(function(e){
86	      if(window.console&&console.warn)console.warn('[silent madi-15]',e&&e.message);
87	      if (typeof onNoChild === 'function') onNoChild();
88	    });
89	}
90	
91	// 활성 자녀 변경 — 셀렉터 UI 에서 호출
92	function setActiveParentChild(idx) {
93	  if (!window._parentChildren) return;
94	  idx = parseInt(idx, 10);
95	  if (isNaN(idx) || idx < 0 || idx >= window._parentChildren.length) return;
96	  if (idx === window._parentActiveIdx) return;
97	  window._parentActiveIdx = idx;
98	  // 활성 자녀 표시 라벨 즉시 갱신
99	  var c = window._parentChildren[idx];
100	  window._parentChildId   = c.child_id;
101	  window._parentCenterId  = c.center_id;
102	  window._parentChildName = c.name || '';
103	  document.querySelectorAll('.parentChildNameLabel').forEach(function(el){ el.textContent = c.name || ''; });
104	  renderParentChildSwitcher();
