9	<style>
10	  * { box-sizing:border-box; }
11	  body { margin:0; font-family:'Inter','Noto Sans KR',sans-serif; background:#f7f9fb; color:#0f172a; min-height:100vh; -webkit-font-smoothing:antialiased; }
