13	  /* ── 레이아웃 (⑤ 와 동일) ── */
14	  .app { display:grid; grid-template-columns:228px 1fr; min-height:100vh; }
15	  .sidebar { background:white; border-right:1px solid #e7ecf2; padding:16px 12px; display:flex; flex-direction:column; }
16	  .brand { display:flex; align-items:center; gap:10px; padding:6px 10px 22px; }
17	  .brand-logo { width:30px; height:30px; border-radius:8px; background:linear-gradient(135deg,#0f3b66,#1e5a93); color:white; display:flex; align-items:center; justify-content:center; font-weight:900; font-size:13.5px; }
18	  .brand-name { font-size:15px; font-weight:800; color:#0f172a; letter-spacing:-0.3px; }
19	  .brand-name span { display:block; font-size:10.5px; color:#94a3b8; font-weight:500; margin-top:1px; }
20	
21	  .nav-section { margin-bottom:18px; }
22	  .nav-label { font-size:10.5px; font-weight:700; color:#94a3b8; padding:0 10px 6px; letter-spacing:0.6px; text-transform:uppercase; }
23	  .nav-item { display:flex; align-items:center; gap:11px; padding:7px 11px; border-radius:7px; font-size:13px; color:#475569; cursor:pointer; margin-bottom:1px; font-weight:500; transition:background 0.12s; }
24	  .nav-item:hover { background:#f1f5f9; color:#0f172a; }
25	  .nav-item.active { background:#eff5fc; color:#0f3b66; font-weight:700; }
26	  .nav-item.active .nav-ic { color:#1e5a93; }
27	  .nav-ic { width:15px; height:15px; flex-shrink:0; color:#64748b; }
