30	  .nav-badge.amber { background:#fef3c7; color:#a16207; }
31	  .nav-badge.blue { background:#dbeafe; color:#1e40af; }
32	
33	  .sidebar-foot { margin-top:auto; padding:10px; border-top:1px solid #f1f5f9; display:flex; align-items:center; gap:10px; }
34	  .avatar { width:30px; height:30px; border-radius:50%; background:linear-gradient(135deg,#0ea5a0,#22c9c3); color:white; display:flex; align-items:center; justify-content:center; font-size:12px; font-weight:800; flex-shrink:0; }
35	  .avatar-text { font-size:12.5px; color:#0f172a; font-weight:700; }
36	  .avatar-role { font-size:10.5px; color:#94a3b8; }
37	  .avatar-status { width:8px; height:8px; border-radius:50%; background:#22c55e; border:2px solid white; margin-left:auto; }
38	
39	  /* ── 상단 바 ── */
40	  .main { display:flex; flex-direction:column; min-width:0; }
41	  .topbar { height:54px; border-bottom:1px solid #e7ecf2; background:white; padding:0 28px; display:flex; align-items:center; justify-content:space-between; }
42	  .top-left { display:flex; align-items:center; gap:14px; }
43	  .breadcrumb { font-size:13px; color:#64748b; }
44	  .breadcrumb b { color:#0f172a; font-weight:600; }
45	  .top-search { display:flex; align-items:center; gap:8px; background:#f1f5f9; padding:7px 14px; border-radius:8px; min-width:280px; }
46	  .top-search input { border:none; background:transparent; font-size:13px; outline:none; flex:1; font-family:inherit; color:#0f172a; }
47	  .top-search input::placeholder { color:#94a3b8; }
48	  .top-search kbd { font-size:10px; color:#94a3b8; padding:1px 5px; background:white; border:1px solid #e2e8f0; border-radius:3px; font-family:'SF Mono',monospace; }
