53	  .icon-btn { width:34px; height:34px; border-radius:8px; border:1px solid #e7ecf2; background:white; cursor:pointer; display:flex; align-items:center; justify-content:center; position:relative; font-size:14px; }
54	  .badge-dot { position:absolute; top:7px; right:7px; width:7px; height:7px; border-radius:50%; background:#ef4444; border:2px solid white; }
