/* ═══════════════════════════════════════════════════════════
   페르소나별 대시보드 (Teacher ⑥ / Admin ⑧)
   - 미리보기 design-previews/06-teacher-home.html, 08-admin-home.html 이식
   - 클래스는 .dp- (dashboard persona) 네임스페이스로 통일해 충돌 회피
   ═══════════════════════════════════════════════════════════ */

.dash-persona { padding:24px 28px 60px; max-width:1400px; margin:0 auto; }
@media (max-width:768px) { .dash-persona { padding:18px 14px 48px; } }

/* 헤더 */
.dp-head { margin-bottom:18px; }
.dp-greeting { font-size:13px; color:#64748b; font-weight:500; margin-bottom:4px; }
.dp-title { font-size:26px; font-weight:900; color:#0f172a; letter-spacing:-0.7px; margin:0; line-height:1.2; }
.dp-sub { font-size:13.5px; color:#475569; margin-top:8px; line-height:1.55; }
.dp-sub b { color:#0f172a; font-weight:700; }
@media (max-width:640px) { .dp-title { font-size:20px; } .dp-sub { font-size:12.5px; } }

/* 시급 배너 (선생님 미작성) */
.dp-urgent {
  display:flex; align-items:center; gap:14px; padding:14px 18px;
  background:linear-gradient(135deg,#fff7ed,#fef3c7);
  border:1px solid #fcd34d; border-radius:13px;
  margin-bottom:18px; box-shadow:0 2px 0 #fbbf24;
}
.dp-urgent-ic { width:44px; height:44px; border-radius:11px; background:#f59e0b; color:white; display:flex; align-items:center; justify-content:center; font-size:22px; flex-shrink:0; box-shadow:0 4px 12px rgba(245,158,11,0.3); }
.dp-urgent-info { flex:1; min-width:0; }
.dp-urgent-title { font-size:14px; font-weight:900; color:#78350f; }
.dp-urgent-text { font-size:12.5px; color:#92400e; margin-top:3px; line-height:1.5; }
.dp-urgent-text b { font-weight:800; }
.dp-urgent-action { padding:9px 16px; border-radius:8px; background:#78350f; color:white; font-weight:800; font-size:12.5px; border:none; cursor:pointer; font-family:inherit; flex-shrink:0; }
.dp-urgent-action:hover { background:#451a03; }
@media (max-width:640px) { .dp-urgent { flex-direction:column; align-items:flex-start; } .dp-urgent-action { width:100%; } }

/* KPI 4개 그리드 */
.dp-kpi-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:1px; background:#e7ecf2; border:1px solid #e7ecf2; border-radius:12px; overflow:hidden; margin-bottom:18px; }
.dp-kpi { background:white; padding:16px 18px; display:flex; align-items:center; gap:12px; }
.dp-kpi-ic { width:40px; height:40px; border-radius:10px; display:flex; align-items:center; justify-content:center; font-size:18px; flex-shrink:0; }
.dp-kic-blue   { background:#dbeafe; color:#1e40af; }
.dp-kic-green  { background:#dcfce7; color:#15803d; }
.dp-kic-purple { background:#ede9fe; color:#6d28d9; }
.dp-kic-rose   { background:#ffe4e6; color:#be123c; }
.dp-kic-amber  { background:#fef3c7; color:#a16207; }
.dp-kpi-info { flex:1; min-width:0; }
.dp-kpi-label { font-size:11.5px; color:#64748b; font-weight:600; margin-bottom:3px; }
.dp-kpi-num { font-size:24px; font-weight:900; color:#0f172a; letter-spacing:-0.7px; line-height:1; }
.dp-kpi-num em { font-size:13px; color:#94a3b8; font-style:normal; font-weight:600; }
.dp-kpi-delta { font-size:10.5px; font-weight:700; margin-top:4px; color:#15803d; }
.dp-kpi-delta.warn { color:#a16207; }
.dp-kpi-delta.flat { color:#94a3b8; }
@media (max-width:1024px) { .dp-kpi-grid { grid-template-columns:repeat(2,1fr); } }
@media (max-width:640px) { .dp-kpi { padding:12px 14px; } .dp-kpi-ic { width:34px; height:34px; font-size:15px; } .dp-kpi-num { font-size:20px; } }

/* 2열 / 풀너비 패널 */
.dp-grid-2 { display:grid; grid-template-columns:1.4fr 1fr; gap:16px; margin-bottom:16px; }
.dp-grid-2-eq { display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-bottom:16px; }
@media (max-width:1024px) { .dp-grid-2, .dp-grid-2-eq { grid-template-columns:1fr; } }

.dp-panel { background:white; border:1px solid #e7ecf2; border-radius:12px; overflow:hidden; margin-bottom:16px; }
.dp-panel-head { padding:14px 18px; border-bottom:1px solid #f1f5f9; display:flex; align-items:center; justify-content:space-between; gap:10px; }
.dp-panel-title { font-size:14px; font-weight:800; color:#0f172a; letter-spacing:-0.2px; }
.dp-panel-sub { font-size:11px; color:#94a3b8; font-weight:500; margin-top:2px; }
.dp-panel-link { font-size:12px; color:#1e5a93; font-weight:700; cursor:pointer; background:none; border:none; padding:0; font-family:inherit; }
.dp-panel-link:hover { color:#0f3b66; }
.dp-panel-body { padding:14px 18px; }
.dp-empty { padding:20px 12px; text-align:center; color:#94a3b8; font-size:12.5px; }

/* 오늘 일정 타임라인 (Teacher) */
.dp-day-sum { display:flex; align-items:center; gap:12px; padding:10px 14px; background:#f8fafc; border:1px solid #e7ecf2; border-radius:10px; margin-bottom:12px; }
.dp-day-num { font-size:26px; font-weight:900; color:#0f3b66; line-height:1; letter-spacing:-0.6px; }
.dp-day-text { font-size:11.5px; color:#64748b; font-weight:600; }
.dp-day-text b { display:block; color:#0f172a; font-size:13px; font-weight:800; margin-bottom:2px; }
.dp-day-right { margin-left:auto; font-size:12px; color:#475569; }
.dp-day-right b { color:#0f3b66; font-weight:800; }

.dp-tl-row { display:grid; grid-template-columns:62px 14px 1fr; gap:12px; padding:9px 0; align-items:center; position:relative; cursor:pointer; }
.dp-tl-row + .dp-tl-row::before { content:""; position:absolute; left:73px; top:-6px; width:2px; height:22px; background:#e2e8f0; }
.dp-tl-time { font-size:13px; color:#0f172a; font-weight:800; font-variant-numeric:tabular-nums; text-align:right; }
.dp-tl-time em { display:block; font-size:10.5px; color:#94a3b8; font-style:normal; font-weight:600; margin-top:1px; }
.dp-tl-dot { width:14px; height:14px; border-radius:50%; background:white; border:3px solid #0ea5a0; box-shadow:0 0 0 3px rgba(14,165,160,0.12); }
.dp-tl-row.done .dp-tl-dot { background:#0ea5a0; }
.dp-tl-row.upcoming .dp-tl-dot { background:white; border-color:#cbd5e1; box-shadow:none; }
.dp-tl-card { padding:10px 13px; background:#f8fafc; border:1px solid #e7ecf2; border-radius:9px; display:flex; align-items:center; gap:10px; transition:all 0.12s; }
.dp-tl-card:hover { background:#eff5fc; border-color:#c7ddf2; }
.dp-tl-row.done .dp-tl-card { background:white; border-color:#e2e8f0; opacity:0.7; }
.dp-tl-av { width:30px; height:30px; border-radius:9px; color:white; display:flex; align-items:center; justify-content:center; font-size:11.5px; font-weight:800; flex-shrink:0; }
.dp-tl-info { flex:1; min-width:0; }
.dp-tl-name { font-size:13px; font-weight:700; color:#0f172a; }
.dp-tl-meta { font-size:11px; color:#64748b; margin-top:1px; }
.dp-tl-tag { font-size:10.5px; padding:2px 8px; border-radius:8px; font-weight:700; flex-shrink:0; }
.dp-tl-tag.done    { background:#dcfce7; color:#15803d; }
.dp-tl-tag.now     { background:#dbeafe; color:#1e40af; }
.dp-tl-tag.upcoming{ background:#f1f5f9; color:#64748b; }

/* 메시지 (Teacher) */
.dp-msg-row { display:flex; gap:10px; padding:11px 0; border-top:1px solid #f1f5f9; cursor:pointer; transition:padding 0.12s; }
.dp-msg-row:first-child { border-top:none; }
.dp-msg-row:hover { padding-left:4px; }
.dp-msg-av { width:32px; height:32px; border-radius:50%; color:white; display:flex; align-items:center; justify-content:center; font-size:12px; font-weight:800; flex-shrink:0; }
.dp-msg-info { flex:1; min-width:0; }
.dp-msg-top { display:flex; align-items:center; gap:6px; }
.dp-msg-from { font-size:12.5px; font-weight:700; color:#0f172a; }
.dp-msg-unread { width:7px; height:7px; border-radius:50%; background:#ef4444; }
.dp-msg-time { font-size:10.5px; color:#94a3b8; margin-left:auto; font-weight:600; }
.dp-msg-preview { font-size:12px; color:#64748b; line-height:1.5; margin-top:3px; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; }

/* 담당 아동 카드 (Teacher) */
.dp-children { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; }
.dp-child { padding:12px; background:#f8fafc; border:1px solid #e7ecf2; border-radius:10px; cursor:pointer; transition:all 0.12s; }
.dp-child:hover { background:white; border-color:#0ea5a0; box-shadow:0 4px 12px rgba(14,165,160,0.1); }
.dp-child-head { display:flex; align-items:center; gap:9px; margin-bottom:9px; }
.dp-child-av { width:32px; height:32px; border-radius:10px; color:white; display:flex; align-items:center; justify-content:center; font-size:11.5px; font-weight:800; flex-shrink:0; }
.dp-child-name { font-size:13px; font-weight:800; color:#0f172a; }
.dp-child-meta { font-size:10.5px; color:#64748b; margin-top:1px; }
.dp-child-last { font-size:11px; color:#64748b; padding-top:8px; border-top:1px dashed #e2e8f0; }
.dp-child-last b { color:#0f172a; font-weight:700; }
@media (max-width:1024px) { .dp-children { grid-template-columns:repeat(2,1fr); } }
@media (max-width:640px) { .dp-children { grid-template-columns:1fr; } }

/* 이번 주 요약 (Teacher) */
.dp-week { display:flex; align-items:center; gap:10px; }
.dp-week-item { flex:1; padding:13px 10px; background:#f8fafc; border:1px solid #e7ecf2; border-radius:10px; text-align:center; }
.dp-week-num { font-size:21px; font-weight:900; color:#0f172a; letter-spacing:-0.4px; line-height:1; }
.dp-week-label { font-size:11px; color:#64748b; font-weight:600; margin-top:4px; }

/* 매출 히어로 (Admin) */
.dp-rev {
  display:grid; grid-template-columns:1.4fr 1fr 1fr; gap:0;
  background:linear-gradient(135deg,#0f3b66 0%,#1e5a93 100%);
  color:white; border-radius:16px; overflow:hidden;
  margin-bottom:18px; position:relative;
  box-shadow:0 10px 28px rgba(15,59,102,0.18);
}
.dp-rev::before { content:""; position:absolute; top:-80px; right:-60px; width:280px; height:280px; border-radius:50%; background:radial-gradient(circle,rgba(251,191,36,0.15) 0%,transparent 70%); pointer-events:none; }
.dp-rev-main { padding:22px 26px; position:relative; z-index:1; }
.dp-rev-label { font-size:11px; font-weight:700; color:rgba(255,255,255,0.7); letter-spacing:0.5px; text-transform:uppercase; }
.dp-rev-num { font-size:32px; font-weight:900; color:white; letter-spacing:-1px; line-height:1; margin-top:8px; }
.dp-rev-num em { font-size:16px; color:rgba(255,255,255,0.7); font-style:normal; font-weight:600; margin-left:4px; }
.dp-rev-meta { font-size:11.5px; color:rgba(255,255,255,0.7); margin-top:8px; line-height:1.55; }
.dp-rev-tag { display:inline-block; padding:3px 10px; background:rgba(252,211,77,0.18); color:#fcd34d; border:1px solid rgba(252,211,77,0.3); border-radius:8px; font-size:10.5px; font-weight:800; margin-top:8px; letter-spacing:0.2px; }
.dp-rev-sub { padding:22px 20px; border-left:1px solid rgba(255,255,255,0.12); position:relative; z-index:1; }
.dp-rev-sub-label { font-size:11px; color:rgba(255,255,255,0.7); font-weight:700; letter-spacing:0.5px; text-transform:uppercase; }
.dp-rev-sub-num { font-size:20px; font-weight:900; color:white; letter-spacing:-0.4px; margin-top:6px; }
.dp-rev-sub-num em { font-size:12px; color:rgba(255,255,255,0.6); font-style:normal; font-weight:600; }
.dp-rev-sub-meta { font-size:11.5px; color:rgba(255,255,255,0.65); margin-top:6px; line-height:1.5; }
.dp-rev-sub-meta b { color:#fcd34d; }
@media (max-width:1024px) { .dp-rev { grid-template-columns:1fr; } .dp-rev-sub { border-left:none; border-top:1px solid rgba(255,255,255,0.12); } }
@media (max-width:640px) { .dp-rev-num { font-size:26px; } }

/* 선생님 활동표 (Admin) */
.dp-trow { display:grid; grid-template-columns:auto 1fr 60px 60px 60px; gap:12px; align-items:center; padding:10px 0; border-top:1px solid #f1f5f9; }
.dp-trow:first-child { border-top:none; }
.dp-trow.head { font-size:10.5px; color:#94a3b8; font-weight:700; letter-spacing:0.3px; text-transform:uppercase; padding-bottom:8px; border-bottom:1px solid #f1f5f9; border-top:none; }
.dp-trow.head .dp-tav { background:transparent !important; }
.dp-tav { width:32px; height:32px; border-radius:50%; color:white; display:flex; align-items:center; justify-content:center; font-size:12px; font-weight:800; flex-shrink:0; }
.dp-tinfo { min-width:0; }
.dp-tname { font-size:12.5px; font-weight:700; color:#0f172a; }
.dp-tmeta { font-size:10.5px; color:#64748b; margin-top:1px; }
.dp-tstat { text-align:center; }
.dp-tstat-num { font-size:13.5px; font-weight:800; color:#0f172a; letter-spacing:-0.2px; }
.dp-tstat-num.warn { color:#a16207; }
.dp-tstat-label { font-size:10px; color:#94a3b8; margin-top:1px; font-weight:600; }
@media (max-width:640px) { .dp-trow { grid-template-columns:auto 1fr; row-gap:4px; } .dp-trow.head { display:none; } .dp-tstat { text-align:left; padding-left:44px; } }

/* 변동 아동 (Admin) */
.dp-change-sum { display:grid; grid-template-columns:repeat(3,1fr); gap:1px; background:#f1f5f9; border:1px solid #e7ecf2; border-radius:10px; overflow:hidden; margin-bottom:12px; }
.dp-change-cell { background:white; padding:13px 10px; text-align:center; }
.dp-change-num { font-size:19px; font-weight:900; line-height:1; letter-spacing:-0.3px; }
.dp-change-num.up { color:#15803d; }
.dp-change-num.flat { color:#475569; }
.dp-change-num.done { color:#1e40af; }
.dp-change-label { font-size:10.5px; color:#64748b; margin-top:4px; font-weight:600; }
.dp-change-row { display:flex; align-items:center; gap:10px; padding:10px 0; border-top:1px solid #f1f5f9; }
.dp-change-row:first-child { border-top:none; }
.dp-change-row .dp-tav { width:28px; height:28px; font-size:10.5px; border-radius:8px; }
.dp-change-content { flex:1; min-width:0; }
.dp-change-title { font-size:12px; font-weight:700; color:#0f172a; }
.dp-change-detail { font-size:10.5px; color:#64748b; margin-top:1px; }
.dp-change-tag { font-size:10px; padding:2px 7px; border-radius:6px; font-weight:700; flex-shrink:0; }
.dp-change-tag.new  { background:#dcfce7; color:#15803d; }
.dp-change-tag.done { background:#dbeafe; color:#1e40af; }
.dp-change-tag.wait { background:#fef3c7; color:#a16207; }

/* 차트 (Admin 추이) */
.dp-chart { position:relative; height:180px; margin:6px 0 4px; padding:0 4px; }
.dp-chart-grid { position:absolute; inset:6px 4px; display:flex; flex-direction:column; justify-content:space-between; pointer-events:none; }
.dp-chart-grid-line { border-top:1px dashed #f1f5f9; }
.dp-chart-svg { position:absolute; inset:6px 4px; width:calc(100% - 8px); height:calc(100% - 12px); }
.dp-chart-x { display:flex; justify-content:space-between; padding:6px 4px 0; font-size:10.5px; color:#94a3b8; font-weight:600; }
.dp-chart-legend { display:flex; gap:16px; padding:8px 0 0; flex-wrap:wrap; }
.dp-chart-leg { display:flex; align-items:center; gap:6px; font-size:11.5px; color:#475569; font-weight:600; }
.dp-chart-leg-dot { width:10px; height:3px; border-radius:2px; }
.dp-chart-leg.ok { color:#15803d; font-weight:800; }

/* 아바타 색상 (공통 — Teacher/Admin) */
