    }).join('') + '</div>';
  }
  html += '</div></div>';

  // 하단 2열: 이번 주 활동 + 빠른 액션
  html += '<div class="dp-grid-2-eq">';

  // 이번 주 활동
  html += ''
    + '<div class="dp-panel">'
    +   '<div class="dp-panel-head">'
