   - parentPanelHome 안에서 사용 (.dp-p- 네임스페이스)
   ═══════════════════════════════════════════════════════════ */
.dp-parent { padding:14px; max-width:1200px; margin:0 auto; }
@media (min-width:768px) { .dp-parent { padding:24px 28px 60px; } }

.dp-p-head { margin-bottom:16px; }
.dp-p-greeting { font-size:13px; color:#64748b; font-weight:500; margin-bottom:4px; }
.dp-p-title { font-size:22px; font-weight:900; color:#0f172a; letter-spacing:-0.5px; margin:0; line-height:1.25; }
.dp-p-sub { font-size:13px; color:#475569; margin-top:6px; line-height:1.55; }
.dp-p-sub b { color:#be185d; font-weight:700; }

/* 자녀 히어로 */
.dp-p-hero {
  display:grid; grid-template-columns:auto 1fr auto; gap:20px;
  padding:22px 24px; margin-bottom:16px;
  background:linear-gradient(135deg,#fdf2f8 0%,#ffffff 55%,#f0fdfa 100%);
  border:1px solid #fbcfe8; border-radius:18px;
  align-items:center; position:relative; overflow:hidden;
}
.dp-p-hero::after { content:""; position:absolute; top:-60px; right:-30px; width:200px; height:200px; border-radius:50%; background:radial-gradient(circle,rgba(236,72,153,0.08) 0%,transparent 70%); pointer-events:none; }
.dp-p-hero-av { position:relative; z-index:1; }
.dp-p-hero-img { width:72px; height:72px; border-radius:20px; color:white; display:flex; align-items:center; justify-content:center; font-size:28px; font-weight:900; box-shadow:0 8px 24px rgba(14,165,160,0.25); }
.dp-p-hero-status { position:absolute; bottom:-4px; right:-4px; padding:3px 9px; background:white; border:2px solid #fce7f3; border-radius:10px; font-size:10.5px; font-weight:800; color:#be185d; }
.dp-p-hero-info { position:relative; z-index:1; min-width:0; }
.dp-p-hero-row { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.dp-p-hero-name { font-size:22px; font-weight:900; color:#0f172a; letter-spacing:-0.4px; }
.dp-p-hero-tag { font-size:11px; padding:3px 9px; border-radius:8px; background:white; border:1px solid #e2e8f0; color:#475569; font-weight:700; }
.dp-p-hero-diag { font-size:12.5px; color:#64748b; margin-top:4px; }
.dp-p-hero-diag b { color:#0f172a; font-weight:700; }
.dp-p-hero-stats { display:flex; gap:18px; margin-top:12px; flex-wrap:wrap; }
.dp-p-hero-stat { font-size:11px; color:#64748b; }
.dp-p-hero-stat b { display:block; font-size:17px; font-weight:900; color:#0f172a; letter-spacing:-0.3px; line-height:1; margin-bottom:3px; }
.dp-p-hero-stat b.good { color:#15803d; }
.dp-p-hero-next { position:relative; z-index:1; padding:14px 18px; background:white; border:1px solid #fbcfe8; border-radius:13px; text-align:center; min-width:160px; }
.dp-p-hero-next-label { font-size:11px; color:#be185d; font-weight:800; letter-spacing:0.3px; }
.dp-p-hero-next-time { font-size:17px; font-weight:900; color:#0f172a; letter-spacing:-0.3px; margin-top:5px; }
.dp-p-hero-next-date { font-size:11.5px; color:#64748b; margin-top:2px; }
.dp-p-hero-next-teacher { font-size:11.5px; color:#475569; margin-top:5px; padding-top:5px; border-top:1px dashed #fbcfe8; font-weight:600; }
@media (max-width:768px) {
  .dp-p-hero { grid-template-columns:1fr; padding:18px; gap:14px; text-align:center; }
  .dp-p-hero-av { margin:0 auto; }
  .dp-p-hero-stats { justify-content:center; }
  .dp-p-hero-row { justify-content:center; }
}

/* 세션 카드 (이번 주 민서가 했어요) */
.dp-p-sess { display:flex; gap:12px; padding:12px 0; border-top:1px solid #f1f5f9; cursor:pointer; transition:padding 0.12s; }
.dp-p-sess:first-child { border-top:none; }
.dp-p-sess:hover { padding-left:4px; }
.dp-p-sess-date { width:54px; flex-shrink:0; text-align:center; padding:7px 0; background:#fdf2f8; border-radius:8px; }
.dp-p-sess-date-num { font-size:17px; font-weight:900; color:#be185d; line-height:1; }
.dp-p-sess-date-day { font-size:10.5px; color:#9d174d; font-weight:700; margin-top:2px; }
.dp-p-sess-content { flex:1; min-width:0; }
.dp-p-sess-title { font-size:13px; font-weight:700; color:#0f172a; }
.dp-p-sess-desc { font-size:12px; color:#64748b; line-height:1.55; margin-top:4px; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; }
.dp-p-sess-tags { display:flex; gap:5px; margin-top:7px; flex-wrap:wrap; }
.dp-p-sess-tag { font-size:10.5px; padding:2px 8px; border-radius:6px; background:#f1f5f9; color:#475569; font-weight:600; }
.dp-p-sess-tag.good { background:#dcfce7; color:#15803d; }

/* 선생님 메시지 카드 */
.dp-p-msg { padding:13px 14px; background:#fefce8; border:1px solid #fde68a; border-radius:11px; margin-bottom:10px; cursor:pointer; }
.dp-p-msg:last-child { margin-bottom:0; }
.dp-p-msg:hover { background:#fef3c7; }
.dp-p-msg-head { display:flex; align-items:center; gap:8px; margin-bottom:6px; }
.dp-p-msg-av { width:26px; height:26px; border-radius:50%; color:white; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:800; }
.dp-p-msg-from { font-size:12.5px; font-weight:800; color:#0f172a; }
.dp-p-msg-time { font-size:10.5px; color:#94a3b8; font-weight:600; margin-left:auto; }
.dp-p-msg-body { font-size:12.5px; color:#475569; line-height:1.6; }
.dp-p-msg-body b { color:#0f172a; font-weight:700; }

/* 발달 추이 그래프 */
.dp-p-chart-area { position:relative; height:180px; margin:10px 0 4px; }
.dp-p-chart-grid { position:absolute; inset:6px 0; display:flex; flex-direction:column; justify-content:space-between; pointer-events:none; }
.dp-p-chart-grid-line { border-top:1px dashed #f1f5f9; }
.dp-p-chart-svg { position:absolute; inset:6px 0; width:100%; height:calc(100% - 12px); }
.dp-p-chart-x { display:flex; justify-content:space-between; padding:6px 4px 0; font-size:10.5px; color:#94a3b8; font-weight:600; }
.dp-p-chart-sum { display:grid; grid-template-columns:repeat(3,1fr); gap:1px; background:#f1f5f9; border:1px solid #e7ecf2; border-radius:10px; overflow:hidden; margin-top:14px; }
.dp-p-chart-cell { background:white; padding:11px 12px; text-align:center; }
.dp-p-chart-num { font-size:17px; font-weight:900; color:#0f172a; letter-spacing:-0.3px; line-height:1; }
.dp-p-chart-num.good { color:#15803d; }
.dp-p-chart-label { font-size:10.5px; color:#64748b; font-weight:600; margin-top:4px; }

/* 가정 활동 */
.dp-p-act { display:flex; gap:11px; padding:11px 0; border-top:1px solid #f1f5f9; align-items:flex-start; }
.dp-p-act:first-child { border-top:none; }
.dp-p-act-num { width:26px; height:26px; border-radius:8px; background:#fdf2f8; color:#be185d; display:flex; align-items:center; justify-content:center; font-size:12px; font-weight:900; flex-shrink:0; }
.dp-p-act-text { flex:1; min-width:0; }
.dp-p-act-text b { display:block; font-size:12.5px; font-weight:700; color:#0f172a; line-height:1.4; }
.dp-p-act-text span { display:block; font-size:11.5px; color:#64748b; margin-top:3px; line-height:1.55; }
.dp-p-act-check { width:20px; height:20px; border-radius:6px; border:1.5px solid #cbd5e1; cursor:pointer; flex-shrink:0; margin-top:3px; transition:all 0.12s; display:flex; align-items:center; justify-content:center; font-size:12px; color:transparent; }
.dp-p-act-check:hover { border-color:#ec4899; }
.dp-p-act-check.done { background:#ec4899; border-color:#ec4899; color:white; }

/* 바우처 */
.dp-p-voucher { padding:13px 14px; background:#f8fafc; border:1px solid #e7ecf2; border-radius:10px; margin-bottom:12px; }
.dp-p-voucher-top { display:flex; align-items:center; justify-content:space-between; margin-bottom:8px; }
.dp-p-voucher-label { font-size:11.5px; color:#64748b; font-weight:600; }
.dp-p-voucher-val { font-size:13px; font-weight:800; color:#0f172a; }
.dp-p-voucher-val b { color:#be185d; font-size:17px; }
.dp-p-voucher-prog { height:8px; background:#f1f5f9; border-radius:4px; overflow:hidden; }
.dp-p-voucher-prog-bar { height:100%; background:linear-gradient(90deg,#ec4899,#f43f5e); border-radius:4px; }
.dp-p-voucher-foot { display:flex; justify-content:space-between; font-size:11px; color:#94a3b8; font-weight:600; margin-top:6px; }
.dp-p-next-row { display:flex; align-items:center; gap:11px; padding:10px 12px; background:white; border:1px solid #e7ecf2; border-radius:9px; margin-bottom:7px; }
.dp-p-next-row:last-child { margin-bottom:0; }
.dp-p-next-day { width:44px; flex-shrink:0; text-align:center; }
.dp-p-next-day-num { font-size:17px; font-weight:900; color:#0f172a; line-height:1; }
.dp-p-next-day-mo { font-size:10.5px; color:#94a3b8; font-weight:700; }
.dp-p-next-info { flex:1; min-width:0; }
.dp-p-next-time { font-size:12.5px; font-weight:700; color:#0f172a; }
.dp-p-next-teacher { font-size:11px; color:#64748b; margin-top:2px; }

.dp-p-link { color:#be185d !important; }
.dp-p-link:hover { color:#9d174d !important; }

