.dp-p-act:first-child { border-top:none; }
.dp-p-act-num { width:26px; height:26px; border-radius:8px; background:#fdf2f8; color:#be185d; display:flex; align-items:center; justify-content:center; font-size:12px; font-weight:900; flex-shrink:0; }
.dp-p-act-text { flex:1; min-width:0; }
.dp-p-act-text b { display:block; font-size:12.5px; font-weight:700; color:#0f172a; line-height:1.4; }
.dp-p-act-text span { display:block; font-size:11.5px; color:#64748b; margin-top:3px; line-height:1.55; }
.dp-p-act-check { width:20px; height:20px; border-radius:6px; border:1.5px solid #cbd5e1; cursor:pointer; flex-shrink:0; margin-top:3px; transition:all 0.12s; display:flex; align-items:center; justify-content:center; font-size:12px; color:transparent; }
.dp-p-act-check:hover { border-color:#ec4899; }
.dp-p-act-check.done { background:#ec4899; border-color:#ec4899; color:white; }

/* 바우처 */
.dp-p-voucher { padding:13px 14px; background:#f8fafc; border:1px solid #e7ecf2; border-radius:10px; margin-bottom:12px; }
.dp-p-voucher-top { display:flex; align-items:center; justify-content:space-between; margin-bottom:8px; }
.dp-p-voucher-label { font-size:11.5px; color:#64748b; font-weight:600; }
.dp-p-voucher-val { font-size:13px; font-weight:800; color:#0f172a; }
.dp-p-voucher-val b { color:#be185d; font-size:17px; }
.dp-p-voucher-prog { height:8px; background:#f1f5f9; border-radius:4px; overflow:hidden; }
.dp-p-voucher-prog-bar { height:100%; background:linear-gradient(90deg,#ec4899,#f43f5e); border-radius:4px; }
.dp-p-voucher-foot { display:flex; justify-content:space-between; font-size:11px; color:#94a3b8; font-weight:600; margin-top:6px; }
.dp-p-next-row { display:flex; align-items:center; gap:11px; padding:10px 12px; background:white; border:1px solid #e7ecf2; border-radius:9px; margin-bottom:7px; }
.dp-p-next-row:last-child { margin-bottom:0; }
.dp-p-next-day { width:44px; flex-shrink:0; text-align:center; }
.dp-p-next-day-num { font-size:17px; font-weight:900; color:#0f172a; line-height:1; }
.dp-p-next-day-mo { font-size:10.5px; color:#94a3b8; font-weight:700; }
.dp-p-next-info { flex:1; min-width:0; }
.dp-p-next-time { font-size:12.5px; font-weight:700; color:#0f172a; }
.dp-p-next-teacher { font-size:11px; color:#64748b; margin-top:2px; }

.dp-p-link { color:#be185d !important; }
.dp-p-link:hover { color:#9d174d !important; }

