    var meta = (c ? (c.type || '') : '') + (age ? (c && c.type ? ' · ' : '') + age + '세' : '');
    var tag = done ? '<span class="dp-tl-tag done">완료</span>' : '<span class="dp-tl-tag upcoming">예정</span>';
    var cls = done ? 'done' : 'upcoming';
    return ''

