1	<!DOCTYPE html>
2	<html lang="ko">
3	<head>
4	<meta charset="UTF-8">
5	<title>① Linear Minimal — 아이마디 대시보드 미리보기</title>
6	<link rel="preconnect" href="https://fonts.googleapis.com">
7	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
8	<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Noto+Sans+KR:wght@400;500;700;800&display=swap" rel="stylesheet">
9	<style>
10	  * { box-sizing:border-box; }
11	  body { margin:0; font-family:'Inter','Noto Sans KR',sans-serif; background:#fafafa; color:#0a0a0a; min-height:100vh; }
12	
13	  /* 레이아웃 */
14	  .app { display:grid; grid-template-columns:240px 1fr; min-height:100vh; }
15	
16	  /* 사이드바 */
17	  .sidebar { background:white; border-right:1px solid #ebebeb; padding:18px 12px; display:flex; flex-direction:column; }
18	  .brand { display:flex; align-items:center; gap:10px; padding:8px 10px 24px; }
19	  .brand-logo { width:28px; height:28px; border-radius:8px; background:linear-gradient(135deg,#0ea5a0,#22c9c3); display:flex; align-items:center; justify-content:center; color:white; font-weight:900; font-size:14px; }
