file.content:
body.dark-mode #tabBtnHome.active .tab-ico { background: var(--mint); }
* { box-sizing:border-box; margin:0; padding:0; -webkit-tap-highlight-color:transparent; }
body { font-family:'Noto Sans KR',sans-serif; background:var(--bg); color:var(--text); min-height:100%; word-break:keep-all; overflow-wrap:break-word; }

.header { background:linear-gradient(135deg,#3b82f6 0%,#0ea5a0 100%); padding:calc(16px + env(safe-area-inset-top, 0px)) calc(20px + env(safe-area-inset-right, 0px)) 12px calc(20px + env(safe-area-inset-left, 0px)); display:flex; align-items:center; justify-content:space-between; box-shadow:0 2px 16px rgba(59,130,246,0.3); }
.logo { display:flex; align-items:center; gap:10px; }
.logo-icon { width:38px; height:38px; background:rgba(255,255,255,0.2); border-radius:10px; display:flex; align-items:center; justify-content:center; font-size:19px; border:1.5px solid rgba(255,255,255,0.3); backdrop-filter:blur(4px); }
.logo-text { color:white; }
.logo-text h1 { font-family:'Raleway',sans-serif; font-size:20px; letter-spacing:0.5px; }
.logo-text p { font-size:11px; opacity:0.55; margin-top:1px; }
.child-count-badge { background:rgba(255,255,255,0.18); color:white; font-size:11px; font-weight:700; padding:4px 10px; border-radius:20px; border:1px solid rgba(255,255,255,0.3); }

.apikey-bar { background:var(--navy2); padding:9px 16px; display:flex; align-items:center; gap:8px; }
.apikey-bar label { color:#94a3b8; font-size:12px; white-space:nowrap; }
.apikey-bar input { flex:1; background:rgba(255,255,255,0.07); border:1px solid rgba(255,255,255,0.12); color:white; padding:7px 12px; border-radius:8px; font-size:13px; font-family:monospace; }
.apikey-bar input::placeholder { color:rgba(255,255,255,0.3); }
.apikey-bar input:focus { outline:none; border-color:var(--mint); }

/* ─── PC 사이드바 레이아웃 (768px+) ─── */
@media (min-width:768px) {
  .tabs { display:none !important; }
  .app-layout { display:flex; height:calc(100dvh - 72px); overflow:hidden; }
  .sidebar {
    width:180px; flex-shrink:0;
    background:var(--white); color:var(--text);
    display:flex; flex-direction:column;
    border-right:1px solid var(--border);
    overflow-y:auto; overflow-x:hidden;
    transition:width 0.22s cubic-bezier(0.4,0,0.2,1);
  }
  /* 접힌 상태 */
  .sidebar.collapsed { width:52px; }
  .sidebar.collapsed .s-lbl { opacity:0; max-width:0; }
  .sidebar.collapsed .sidebar-item { justify-content:center; padding:10px 0; gap:0; }
  .sidebar.collapsed .sidebar-divider { margin:6px 8px; }
  /* 접힌 상태 툴팁 */
  .sidebar.collapsed .sidebar-item { position:relative; }
  .sidebar.collapsed .sidebar-item:hover::after {
    content: attr(data-tooltip);
    position:absolute; left:calc(100% + 8px); top:50%; transform:translateY(-50%);
    background:#2563eb; color:white; font-size:12px; font-weight:500;
    padding:5px 10px; border-radius:7px; white-space:nowrap;
    pointer-events:none; z-index:999;
    box-shadow:0 2px 10px rgba(37,99,235,0.3);
  }
  .sidebar-nav { display:flex; flex-direction:column; gap:2px; padding:12px 8px; flex:1; }
  .sidebar-item {
    display:flex; align-items:center; gap:10px;
    padding:10px 12px; border-radius:10px;
    font-size:13px; font-weight:500; color:var(--text2);
    cursor:pointer;
    transition:background 0.15s, color 0.15s, padding 0.22s cubic-bezier(0.4,0,0.2,1), gap 0.22s cubic-bezier(0.4,0,0.2,1);
    touch-action:manipulation; user-select:none;
    border:none; background:none; text-align:left; width:100%;
  }
  .sidebar-item:hover { background:var(--bg); color:var(--text); }
  .sidebar-item.active { background:#dbeafe; color:#2563eb; }
  body.dark-mode .sidebar-item.active { background:rgba(59,130,246,0.2); color:#93c5fd; }
  /* 접힘 상태: 활성 메뉴에 좌측 3px 파란 막대 (좁은 공간에서 현재 위치 강조) */
  .sidebar.collapsed .sidebar-item.active { box-shadow:inset 3px 0 0 #2563eb; }
  body.dark-mode .sidebar.collapsed .sidebar-item.active { box-shadow:inset 3px 0 0 #93c5fd; }
  .sidebar-item .s-ico { font-size:16px; width:22px; text-align:center; flex-shrink:0; }
  .sidebar-item .s-lbl {
    font-size:13px;
    white-space:nowrap;
    overflow:hidden;
    max-width:160px;
    opacity:1;
    transition:opacity 0.18s ease, max-width 0.22s cubic-bezier(0.4,0,0.2,1);
  }
  .sidebar-divider { height:1px; background:var(--border); margin:6px 12px; }
  .app-main { flex:1; overflow-y:auto; overflow-x:auto; }
  .apikey-bar { margin-left:0; }
  /* 사이드바 토글 버튼 (PC only) */
  .sidebar-toggle-btn {
    display:flex; align-items:center; justify-content:center;
    background:rgba(255,255,255,0.15); border:none; color:white;
    width:30px; height:30px; border-radius:8px; cursor:pointer;
    font-size:16px; flex-shrink:0; transition:background 0.15s;
    touch-action:manipulation;
  }
  .sidebar-toggle-btn:hover { background:rgba(255,255,255,0.28); }
  .sidebar-toggle-btn:active { transform:scale(0.92); background:rgba(255,255,255,0.4); }
  /* 모션 감소 선호 사용자: 즉시 전환 */
  @media (prefers-reduced-motion: reduce) {
    .sidebar, .sidebar-item, .sidebar-item .s-lbl { transition:none !important; }
  }
  /* Breadcrumb (PC only) */
  .breadcrumb-bar {
    display:flex; align-items:center; gap:6px;
    padding:10px 20px; border-bottom:1px solid var(--border);
    background:var(--white); font-size:13px; color:var(--text2);
    flex-shrink:0;
  }
  .breadcrumb-bar .bc-home { color:var(--mint); cursor:pointer; font-weight:600; }

