// ════════════════════════════════════════════════════════════════════
// madi-vocab.js — 한국 언어치료 임상 어휘 사전 + 후처리 검열기
// ════════════════════════════════════════════════════════════════════
//
// 목적: 모든 AI 프롬프트가 일관된 어휘 정책을 따르도록 단일 소스로 통합.
// - 한자어/딱딱한 표현 금지 사전 (학부모용)
// - 음운 오류 패턴 정의 (조음 평가용)
// - 발달 단계별 정상 오류 기준 (발달성/비발달성 판단)
// - 임상 약어·표준 용어 (치료사용)
// - 후처리 sanitize 함수
//
// 이 파일은 index.html 에서 다른 madi-*.js 보다 먼저 로드되어야 함.
// ES5 호환 유지 (var, function, .then).
// ════════════════════════════════════════════════════════════════════

// ── 한자어 → 일상어 (학부모 대상 문서에서만 적용) ──
var SLP_VOCAB_BLOCKED_PARENT = {
  // 동사·서술형
  '통합적 발달을 모색': '여러 영역이 함께 자라고 있어요',
  '정체를 타개': '변화를 주기 위해',
  '도모하다': '함께 해보다',
  '도모합니다': '함께 해봅니다',
  '증진': '늘리기',
  '증진합니다': '늘려갑니다',
  '증진시킵니다': '늘려갑니다',
  '도출': '찾아내기',
  '강화하겠습니다': '더 연습해보겠습니다',
  '구사하다': '쓰다',
  '구사합니다': '씁니다',
  '발화하다': '말하다',
  '발화합니다': '말합니다',
  '발현': '나타남',
  '제반': '여러',
  '심화': '더 깊이',
  '제고': '높이기',

  // 학부모가 어려워하는 임상 용어 → 풀어쓰기
  '발화': '말',
  '음운': '소리',
  '조음': '발음',
  '수용언어': '듣고 이해하는 말',
  '표현언어': '직접 하는 말',
  '구문': '문장 구조',
  '의미관계': '말의 뜻 연결',
  '담화': '대화',
  '화용': '상황에 맞게 말하기',
  '음소': '소리 하나',
  '단음절': '한 글자',
  '이음절': '두 글자',
  '다음절': '여러 글자',

  // 비표준·잘못 쓰이는 용어 (보고서에서 흔히 잘못 쓰임)
  '중지화': '파열음화',   // 사용자 명시: "중지화는 일반적인 보고서에서 쓰지 않음"
  '중지음화': '파열음화',
  '폐쇄음화': '파열음화', // 둘 다 통용되지만 "파열음화"가 표준
  '저해음화': '파열음화'
};

// ── 비표준 → 표준 임상 용어 (모든 문서에서 적용) ──
// 학부모용 아니더라도 잘못된 표기는 통일.
var SLP_VOCAB_BLOCKED_ALL = {
  '중지화': '파열음화',
  '중지음화': '파열음화',
  '저해음화': '파열음화',
  'UTAP2': 'U-TAP',           // U-TAP은 1판이 표준 약어
  'UTAP': 'U-TAP',
  'U TAP': 'U-TAP'
};

// ── 권장 표현 (상황별 예시) ──
var SLP_VOCAB_ENCOURAGED = {
  progress: [
    '말이 늘고 있어요',
    '~을 해냈어요',
    '부쩍 늘었어요',
    '시도가 잦아졌어요',
    '먼저 말을 걸기 시작했어요'
  ],
  plateau: [
    '아직 어려워해요',
    '조금 더 시간이 필요해요',
    '익숙해지는 중이에요',
    '비슷한 수준을 유지하고 있어요'
  ],
  home_tip: [
    '집에서 이렇게 도와주시면 좋아요',
    '5분만 함께 해보세요',
    '식사 시간에 자연스럽게 시도해 보세요'
  ]
};

// ════════════════════════════════════════════════════════════════════
// 음운 오류 패턴 사전 (조음음운장애 평가용)
// ════════════════════════════════════════════════════════════════════
//
// 사용자 지시 (2026-05-21):
// - "사탕→타탕": ㅅ→ㅌ = 파열음화
// - "자동차→타동타": ㅈ→ㅌ = 파열음화 + 전방화 (치경경구개음→치경음)
// - 한 오류에 여러 패턴이 동시에 적용될 수 있음을 보고서에 모두 기술
// - 발달적 오류 vs 비발달적 오류 판단 필수
// ════════════════════════════════════════════════════════════════════

var SLP_PHONO_PATTERNS = {
  // ────── 자음 변동 ──────
  '파열음화': {
    en: 'stopping',
    desc: '마찰음(ㅅ,ㅆ,ㅎ)·파찰음(ㅈ,ㅊ,ㅉ)·유음(ㄹ)을 파열음(ㅂ,ㅃ,ㅍ,ㄷ,ㄸ,ㅌ,ㄱ,ㄲ,ㅋ)으로 대치',
    examples: ['사탕→타탕(ㅅ→ㅌ)', '자동차→타동타(ㅈ→ㅌ)', '쥐→뒤(ㅈ→ㄷ)']
  },
  '전방화': {
    en: 'fronting',
    desc: '연구개음(ㄱ,ㅋ,ㄲ) 또는 치경경구개음(ㅈ,ㅊ,ㅉ)을 더 앞쪽 위치의 음으로 대치',
    examples: ['고양이→도양이(ㄱ→ㄷ)', '자동차→타동타(ㅈ→ㅌ, 치경경구개음→치경음)']
  },
  '후방화': {
    en: 'backing',
    desc: '치경음(ㄷ,ㅌ,ㄸ)을 연구개음(ㄱ,ㅋ,ㄲ)으로 대치 — 비전형적',
    examples: ['타요→카요(ㅌ→ㅋ)']
  },
  '마찰음화': {
    en: 'frication',
    desc: '파열음을 마찰음으로 대치 — 드물게 나타남',
    examples: ['바나나→사나나(ㅂ→ㅅ)']
  },
  '파찰음화': {
    en: 'affrication',
    desc: '마찰음을 파찰음으로 대치',
    examples: ['사과→자과(ㅅ→ㅈ)']
  },
  '활음화': {
    en: 'gliding',
    desc: '유음(ㄹ)을 활음(ㅇ,ㅣ,ㅜ)으로 대치 — 4세 이전 흔함',
    examples: ['라면→야면(ㄹ→ㅇ)']
  },
  '유음화': {
    en: 'liquid_substitution',
    desc: 'ㄹ을 다른 유음으로 대치',
    examples: ['빨대→빠대']
  },
  '비음화': {
    en: 'nasalization',
    desc: '비비음을 비음으로 대치',
    examples: ['빠빠→마마(ㅂ→ㅁ)']
  },
  '탈비음화': {
    en: 'denasalization',
    desc: '비음을 비비음으로 대치 — 드물게 나타남',
    examples: ['엄마→업바(ㅁ→ㅂ)']
  },

  // ────── 음절 구조 변동 ──────
  '음절생략': {
    en: 'syllable_deletion',
    desc: '단어의 음절(주로 약음절)을 통째로 생략',
    examples: ['바나나→나나', '코끼리→끼리']
  },
  '종성생략': {
    en: 'final_consonant_deletion',
    desc: '음절의 종성(받침)을 생략 — 발달적 (3세까지 흔함)',
    examples: ['밥→바', '책→채']
  },
  '초성생략': {
    en: 'initial_consonant_deletion',
    desc: '음절의 초성을 생략 — 비전형적',
    examples: ['공→옹']
  },
  '자음군축약': {
    en: 'cluster_reduction',
    desc: '겹받침이나 자음군을 단순화',
    examples: ['값→갑', '닭→닥']
  },

  // ────── 동화 ──────
  '순행동화': {
    en: 'progressive_assimilation',
    desc: '앞 음소가 뒤 음소를 닮게 하는 동화',
    examples: ['바나나→바바바(앞 ㅂ이 뒤로 전파)']
  },
  '역행동화': {
    en: 'regressive_assimilation',
    desc: '뒤 음소가 앞 음소를 닮게 하는 동화 — 더 흔함',
    examples: ['바지→자지(뒤 ㅈ이 앞으로)']
  }
};

// ════════════════════════════════════════════════════════════════════
// 한국 아동 음운 발달 기준 (Smit, 김영태·신문자 등 종합)
// 연령별로 안정화되는 음소 — 이 연령 이전 오류는 "발달적", 이후 오류는 "비발달적(지연)"
// ════════════════════════════════════════════════════════════════════

var SLP_PHONO_DEV_AGE = {
  // 음소: 안정화 연령 (만 나이, 90% 정조음 기준)
  'ㅂ': 2, 'ㅃ': 2, 'ㅍ': 2,
  'ㅁ': 2, 'ㄴ': 2, 'ㅇ': 2,
  'ㄷ': 3, 'ㄸ': 3, 'ㅌ': 3,
  'ㄱ': 3.5, 'ㄲ': 3.5, 'ㅋ': 3.5,
  'ㅎ': 3,
  'ㅈ': 4.5, 'ㅉ': 4.5, 'ㅊ': 4.5,
  'ㅅ': 5, 'ㅆ': 5,
  'ㄹ': 6
};

// 오류 패턴별 일반적 소실(발달적으로 사라지는) 연령
var SLP_PHONO_PATTERN_DEV_AGE = {
  '파열음화': 4,        // 만 4세까지 발달적, 이후 지연
  '전방화': 4,
  '후방화': 3,          // 3세 이후 비전형적
  '활음화': 5,          // ㄹ→활음은 5세까지 가능
  '종성생략': 3,
  '초성생략': 3,        // 3세 이후 비전형적
  '음절생략': 3,
  '자음군축약': 6,
  '마찰음화': 3,        // 3세 이후 비전형적
  '비음화': 3,
  '탈비음화': 3
};

// ════════════════════════════════════════════════════════════════════
// 임상 약어·표준 용어 (치료사용 메모/보고서 전용)
// ════════════════════════════════════════════════════════════════════

var SLP_CLINICAL_TERMS = {
  // 진단별 핵심 용어
  '조음음운장애': [
    '오조음(misarticulation)',
    '정조음',
    '자극반응도(SR, stimulability)',
    '음소 정확도(PCC, Percentage of Consonants Correct)',
    '오류 일관성',
    '오류 패턴(파열음화/전방화/후방화/활음화/생략/대치/왜곡/첨가)',
    '발달적 오류 vs 비발달적 오류',
    '단어 수준 / 문장 수준 / 자발화 수준'
  ],
  '언어발달장애': [
    'MLU(평균발화길이, Mean Length of Utterance)',
    'MLU-w(어절 단위), MLU-m(형태소 단위)',
    '표현어휘량(어휘 다양도, TTR)',
    '의미관계(행위자-대상-행위, 소유자-대상 등)',
    '구문구조(단문/복문/접속/내포)',
    '의사소통 기능(요구/거부/명명/주의끌기/사회적 상호작용)'
  ],
  '유창성장애': [
    'SLD(Stuttering-Like Disfluency) %',
    'OD(Other Disfluency) %',
    '핵심행동(반복/연장/막힘)',
    '부수행동(눈깜빡임/얼굴 긴장/회피)',
    '말더듬 심도(P-FA, SSI-4)',
    '회피 행동·인식'
  ],
  '자폐스펙트럼': [
    '공동주의(joint attention)',
    '상호적 의사소통(turn-taking)',
    '화용(상황·맥락에 맞는 언어 사용)',
    '반향어(echolalia, 즉각/지연)',
    '비구어적 의사소통(시선/제스처)',
    '의사소통 의도'
  ]
};

// ════════════════════════════════════════════════════════════════════
// 프롬프트에 주입할 컴팩트 가이드 (토큰 절약)
// 각 AI 호출에서 system 프롬프트 끝에 부착.
// ════════════════════════════════════════════════════════════════════

// 학부모 대상 — 한자어 금지 + 권장 표현 + 비표준 용어 교정
var SLP_PROMPT_PARENT_GUIDE = ''
  + '【학부모용 어휘 규칙】'
  + ' 금지(반드시 풀어쓰기): "통합적 발달을 모색"→"여러 영역이 함께 자라요",'
  + ' "정체를 타개"→"변화를 주기 위해", "도모하다"→"함께 해보다", "증진"→"늘리기",'
  + ' "도출"→"찾아내기", "구사하다"→"쓰다", "발화"→"말", "음운"→"소리", "조음"→"발음",'
  + ' "수용언어"→"듣고 이해하는 말", "표현언어"→"직접 하는 말".'
  + ' 비표준 금지: "중지화"→반드시 "파열음화" 또는 "ㅅ을 ㅌ으로 말함" 형태로.'
  + ' 권장: "말이 늘고 있어요", "~을 해냈어요", "집에서 5분만 함께 해보세요" 같은 친근 표현.';

// 치료사용 — 임상 약어/표준 용어 + 비표준 교정
var SLP_PROMPT_CLINICAL_GUIDE = ''
  + '【임상 보고서 어휘 규칙】'
  + ' 표준 용어 사용: "파열음화"(중지화 X), "전방화", "후방화", "활음화", "자음군축약",'
  + ' "자극반응도(SR)", "음소 정확도(PCC)", "MLU(평균발화길이)", "SLD %".'
  + ' 검사명 표기: "우리말 조음·음운 평가(U-TAP)"(UTAP/UTAP2 표기 금지),'
  + ' "수용·표현 어휘력 검사(REVT)", "취학전 아동의 수용언어 및 표현언어 검사(PRES)".'
  + ' 문어체 경어: ~함, ~됨, ~임. 약어는 최초 1회 풀어 쓴 후 약어 사용.';

// 음운 오류 분석 의무 가이드 (조음음운장애 케이스에 부착)
var SLP_PROMPT_PHONO_GUIDE = ''
  + '【조음 오류 분석 필수 항목】'
  + ' 각 오류 음소마다 다음을 모두 기술하세요:'
  + ' (1) 목표음 → 오류음 (예: "사탕→타탕, ㅅ→ㅌ"),'
  + ' (2) 적용되는 오류 패턴 — 한 오류에 여러 패턴이 동시에 적용되면 모두 나열'
  + '     (예: "ㅈ→ㅌ은 파열음화(파찰음→파열음)인 동시에 전방화(치경경구개음→치경음)"),'
  + ' (3) 발달적 오류인지 비발달적 오류인지 판단 (아동 만 나이와 한국 음운 발달 기준 대조),'
  + ' (4) 가능하다면 자극반응도(SR) 또는 일관성 코멘트.'
  + ' 표준 용어 사용: "파열음화"(중지화 X). 사용 가능 패턴: 파열음화, 전방화, 후방화,'
  + ' 마찰음화, 파찰음화, 활음화, 비음화, 탈비음화, 음절생략, 종성생략, 초성생략, 자음군축약,'
  + ' 순행동화, 역행동화.'
  + ' 한국 음소 안정화 연령(90% 정조음): ㅂㅁㄴㅇ ~2세, ㄷㅌ ~3세, ㄱㅋㅎ ~3.5세,'
  + ' ㅈㅊ ~4.5세, ㅅㅆ ~5세, ㄹ ~6세. 파열음화·전방화는 만 4세 이후 비발달적, 후방화는 3세 이후 비발달적.';

// ════════════════════════════════════════════════════════════════════
// 후처리 sanitize 함수 — AI 응답 텍스트에서 비표준/한자어 자동 치환
// audience: 'parent' | 'clinical' | 'mixed'
// ════════════════════════════════════════════════════════════════════

function sanitizeSLPOutput(text, audience) {
  if (typeof text !== 'string' || !text) return text;
  // 1) 모든 문서에서 비표준 용어는 표준으로 통일
  Object.keys(SLP_VOCAB_BLOCKED_ALL).forEach(function(bad){
    text = text.split(bad).join(SLP_VOCAB_BLOCKED_ALL[bad]);
  });
  // 2) 학부모 대상이면 한자어·전문 용어를 일상어로
  if (audience === 'parent') {
    Object.keys(SLP_VOCAB_BLOCKED_PARENT).forEach(function(bad){
      text = text.split(bad).join(SLP_VOCAB_BLOCKED_PARENT[bad]);
    });
  }
  return text;
}

// 진단별 임상 용어 가이드 — system 프롬프트에 부착할 한 줄 요약
function getClinicalGuideForDiagnosis(diagnosis) {
  if (!diagnosis || !SLP_CLINICAL_TERMS[diagnosis]) return '';
  return '【' + diagnosis + ' 핵심 용어】' + SLP_CLINICAL_TERMS[diagnosis].join(', ') + '.';
}

// 전역 노출 (브라우저 환경)
if (typeof window !== 'undefined') {
  window.SLP_VOCAB_BLOCKED_PARENT  = SLP_VOCAB_BLOCKED_PARENT;
  window.SLP_VOCAB_BLOCKED_ALL     = SLP_VOCAB_BLOCKED_ALL;
  window.SLP_VOCAB_ENCOURAGED      = SLP_VOCAB_ENCOURAGED;
  window.SLP_PHONO_PATTERNS        = SLP_PHONO_PATTERNS;
  window.SLP_PHONO_DEV_AGE         = SLP_PHONO_DEV_AGE;
  window.SLP_PHONO_PATTERN_DEV_AGE = SLP_PHONO_PATTERN_DEV_AGE;
  window.SLP_CLINICAL_TERMS        = SLP_CLINICAL_TERMS;
  window.SLP_PROMPT_PARENT_GUIDE   = SLP_PROMPT_PARENT_GUIDE;
  window.SLP_PROMPT_CLINICAL_GUIDE = SLP_PROMPT_CLINICAL_GUIDE;
  window.SLP_PROMPT_PHONO_GUIDE    = SLP_PROMPT_PHONO_GUIDE;
  window.sanitizeSLPOutput         = sanitizeSLPOutput;
  window.getClinicalGuideForDiagnosis = getClinicalGuideForDiagnosis;
}

